#!/usr/bin/env python3
"""Restaure les dossiers du paquet V3 candidate 1 après un upload aplati.

Lecture seule par défaut ; --apply applique la réparation dans le dossier du
script. N'importe aucun module du bot, n'utilise pas le réseau, ne lance aucun
scanner et ne modifie ni base de données, ni armement, ni configuration LIVE.
"""
import argparse
import base64
import gzip
import hashlib
import json
import os
from pathlib import Path
import tempfile

# Empreintes et trois fichiers manquants issus du ZIP original livré.
PACKAGE_DATA = ""


def digest(data):
    return hashlib.sha256(data).hexdigest()


def read_file(root, path):
    relative = path.relative_to(root)
    current = root
    for part in relative.parts:
        current = current / part
        if current.is_symlink():
            raise RuntimeError(f"Lien symbolique refusé : {relative}")
    if path.exists() and not path.is_file():
        raise RuntimeError(f"Fichier attendu : {relative}")
    return path.read_bytes() if path.is_file() else None


def install_new(root, target, content):
    existing = read_file(root, target)
    if existing is not None:
        if existing != content:
            raise RuntimeError(f"Fichier modifié pendant la réparation : {target.name}")
        return
    target.parent.mkdir(parents=True, exist_ok=True)
    # Le lien atomique échoue si la destination vient d'être créée : aucun
    # fichier préexistant n'est écrasé, même en cas de modification concurrente.
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=target.parent, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(temporary, 0o644)
        try:
            os.link(temporary, target)
        except FileExistsError:
            if read_file(root, target) != content:
                raise RuntimeError(f"Destination occupée : {target.relative_to(root)}")
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def repair(root, apply=False):
    root = Path(root).resolve(strict=True)
    package = json.loads(gzip.decompress(base64.b64decode(PACKAGE_DATA)))
    expected = package["sha256"]
    embedded = {p: base64.b64decode(b) for p, b in package["embedded"].items()}
    contents = {}
    additions = []
    # Vérifier toutes les sources et destinations avant la première écriture.
    for name, checksum in expected.items():
        target = root / name
        data = read_file(root, target)
        if data is not None:
            if digest(data) != checksum:
                raise RuntimeError(f"Contenu différent du paquet V3 : {name}. Aucun remplacement.")
        else:
            flat = read_file(root, root / Path(name).name)
            if flat is not None and digest(flat) == checksum:
                data = flat
            elif name in embedded and digest(embedded[name]) == checksum:
                data = embedded[name]
            else:
                raise RuntimeError(f"Source absente ou modifiée : {name}. Aucune écriture.")
            additions.append(name)
        contents[name] = data
    duplicates = {}
    for name in expected:
        flat_name = Path(name).name
        if flat_name in expected or flat_name in duplicates:
            continue
        flat = read_file(root, root / flat_name)
        if flat is not None and any(
            Path(p).name == flat_name and contents[p] == flat for p in expected
        ):
            duplicates[flat_name] = flat
    print(f"Paquet original vérifié : {len(expected)} fichiers.")
    print(f"À créer au bon emplacement : {len(additions)} ; doublons à déplacer : {len(duplicates)}.")
    if not apply:
        print("Aperçu uniquement. Ajouter --apply pour appliquer.")
        return
    for name in additions:
        install_new(root, root / name, contents[name])
    for name, checksum in expected.items():
        data = read_file(root, root / name)
        if data is None or digest(data) != checksum:
            raise RuntimeError(f"Vérification finale incorrecte : {name}. Sources conservées.")
    # Retirer uniquement les copies aplaties dont les octets sont maintenant
    # vérifiés à destination. Les autres fichiers du dépôt restent en place.
    for name, original in duplicates.items():
        if read_file(root, root / name) != original:
            raise RuntimeError(f"Copie racine modifiée : {name}. Conservée.")
    for name in duplicates:
        (root / name).unlink()
    print(f"Arborescence V3 : {len(expected)}/{len(expected)} fichiers conformes au ZIP original.")
    print("Réparation locale terminée. Aucun lancement du scanner, aucun ordre envoyé.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=str(Path(__file__).resolve().parent))
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args()
    try:
        repair(args.root, args.apply)
    except (OSError, ValueError, RuntimeError) as exc:
        parser.exit(1, f"Réparation interrompue : {exc}\n")


if __name__ == "__main__":
    main()
